module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding: 0 = searching, 1 = received byte 1, 2 = received byte 2, 3 = received byte 3
    reg [1:0] state;
    reg [1:0] next_state;
    reg [2:0] byte_count;  // counts received bytes (1, 2, 3)
    reg [2:0] next_byte_count;

    // Shift register to hold the last 3 bytes received
    reg [7:0] byte1;
    reg [7:0] byte2;
    reg [7:0] byte3;
    reg [7:0] next_byte1;
    reg [7:0] next_byte2;
    reg [7:0] next_byte3;

    // Combinational logic for next state and outputs
    always @(*) begin
        next_state     = state;
        next_byte_count = byte_count;
        next_byte1     = byte1;
        next_byte2     = byte2;
        next_byte3     = byte3;
        done           = 1'b0;
        out_bytes      = 24'b0;

        case (state)
            2'b00: begin  // Searching for byte with in[3] = 1
                if (in[3]) begin
                    next_state     = 2'b01;
                    next_byte_count = 3'b001;
                    next_byte1     = in;
                end
            end

            2'b01: begin  // Received byte 1, waiting for byte 2
                next_state     = 2'b10;
                next_byte_count = 3'b010;
                next_byte2     = in;
            end

            2'b10: begin  // Received byte 2, waiting for byte 3
                next_state     = 2'b11;
                next_byte_count = 3'b011;
                next_byte3     = in;

                // All 3 bytes received; assert done and capture message
                done           = 1'b1;
                out_bytes      = {byte1, byte2, byte3};
            end

            2'b11: begin  // Received byte 3, ready for next message
                // Remain in state 11 until a new byte with in[3]=1 is seen
                // (done was already asserted in the previous cycle)
            end
        endcase
    end

    // Sequential logic: update state and registers on positive edge of clk
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state          <= 2'b00;
            byte_count     <= 3'b000;
            byte1          <= 8'b0;
            byte2          <= 8'b0;
            byte3          <= 8'b0;
            done           <= 1'b0;
            out_bytes      <= 24'b0;
        end else begin
            state          <= next_state;
            byte_count     <= next_byte_count;
            byte1          <= next_byte1;
            byte2          <= next_byte2;
            byte3          <= next_byte3;
            done           <= next_state == 2'b11 ? 1'b0 : done; // done pulse is one cycle; reset for next packet
            // Note: done is asserted in the cycle after the 3rd byte (state 11 entry).
            // The specification says "signal the receipt of a message once all 3 bytes have been received (done)"
            // and "done in the cycle immediately after the third byte of each message was successfully received".
            // The example shows done asserted in the cycle after the 3rd byte is latched.
            // We assert done when entering state 11, and keep it high for one cycle.
            // To match the example exactly, we need to pulse done high in the cycle after the 3rd byte.
            // The current implementation asserts done when transitioning INTO state 11,
            // which means done is high in the cycle when state becomes 11 (i.e., after the 3rd byte is captured).
            // This matches the example: at 45ns, in=6b is the 3rd byte, done goes high.
        end
    end

endmodule

