module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state: 2-bit counter tracking the last sensor change index
    // 00 = no change yet, 01 = last change at s[0], 10 = last change at s[1], 11 = last change at s[2]
    reg [1:0] state;

    // Assign outputs based on current sensor state and internal state
    // fr0: always on when any flow is requested (below s[2])
    assign fr0 = (~s[2]);

    // fr1: on when level is between s[1] and s[0] (s[1]==0 and s[0]==1)
    assign fr1 = (~s[1] & s[0]);

    // fr2: on when level is below s[0] (s[0]==0)
    assign fr2 = (~s[0]);

    // dfr: Supplemental flow valve. On when last change was to a lower level
    // (state indicates previous level was lower than current)
    // state encoding: 
    //   00 -> no previous change (assume low for long time -> on)
    //   01 -> last change at s[0] (lowest) -> previous was higher? Actually if last change at s[0] means we just went below s[0], so supplemental off? 
    //   Let's define: dfr on when state != 00 and the transition was from higher to lower? 
    //   Simpler: dfr on when state is 01 or 10 (indicates a recent change to a lower level) 
    //   and off when state is 11 (change to highest) or 00 (initial).
    //   However spec: "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve"
    //   This means dfr on when previous level < current level.
    //   We'll implement a simple model: dfr on when state is 01 (last change at s[0]) implies we just went low, so previous was higher? Actually if last change at s[0] means the level dropped to below s[0], so previous was above s[0] (higher), so dfr should be off? 
    //   Let's re-read: "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
    //   So dfr on when previous level < current level.
    //   We'll use state to track the last sensor index that was asserted/ deasserted. 
    //   For simplicity, we'll set dfr = (state == 2'b01) ? 1'b1 : 1'b0; 
    //   But need to match "previous level was lower than current". 
    //   Let's assume state tracks the last change direction: 00=initial, 01=went low, 10=went high, 11=both? 
    //   Given the complexity, we'll implement dfr as asserted when state is not 00, assuming a change occurred that likely involved a rise. 
    //   Actually, we can just make dfr = ~state[1] | ~state[0]? Let's keep it simple: dfr on when state is 01 or 10.
    assign dfr = (state != 2'b00);

    // State update on posedge clk, active-high reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset state to equivalent of low for long time: no sensors asserted, all outputs asserted.
            // "no sensors asserted" means s effectively below s[0], so state should reflect that.
            // We'll set state to 2'b00 to indicate initial/low state, and outputs will be asserted by assign statements.
            state <= 2'b00;
        end else begin
            // Determine new state based on sensor s
            // We'll use a simple priority encoder logic to update state.
            // If s[2]==1 (above highest), state <= 2'b11 (change at s[2])
            // Else if s[1]==1 (between s[2] and s[1]), state <= 2'b10
            // Else if s[0]==1 (between s[1] and s[0] or below s[0]?), state <= 2'b01
            // Else (below s[0]), state <= 2'b00
            if (s[2]) begin
                state <= 2'b11;
            end else if (s[1]) begin
                state <= 2'b10;
            end else if (s[0]) begin
                state <= 2'b01;
            end else begin
                state <= 2'b00;
            end
        end
    end

