module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: 4-digit BCD
);

    // Internal state register for the 4-digit BCD counter (16 bits)
    logic [15:0] q_reg;

    // Assign output ports
    assign q = q_reg;

    // ena[2] enables the hundreds digit (q[11:8])
    // ena[1] enables the tens digit   (q[7:4])
    // ena[0] enables the ones digit   (q[3:0])
    // We drive ena based on carry-out from the lower digit.
    // For a simple free-running counter, ena is high when the
    // corresponding digit is not at its maximum (9).
    // Here we generate enables based on the current count:
    // ena[i] is high if digit i is less than 9.
    assign ena[2] = q_reg[11:8] < 4'd9;
    assign ena[1] = q_reg[7:4]  < 4'd9;
    assign ena[0] = q_reg[3:0]  < 4'd9;

    // Synchronous always block for the BCD counter
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // Increment the 16-bit register by 1 on each clock
            q_reg <= q_reg + 16'd1;
        end
    end

endmodule

