module TopModule(
    input d,
    input done_counting,
    input ack,
    input [9:0] state,
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // one-hot encoded state bits
    wire S = state[0];
    wire S1 = state[1];
    wire S11 = state[2];
    wire S110 = state[3];
    wire B0 = state[4];
    wire B1 = state[5];
    wire B2 = state[6];
    wire B3 = state[7];
    wire Count = state[8];
    wire Wait = state[9];

    // next-state signals (one-hot)
    wire [9:0] next_state;

    // combinational next-state logic
    assign next_state = 10'b0;
    // S next: from S (d=0) or S110 (d=0) or Wait (ack=1)
    assign next_state[0] = (~d & S) | (~d & S110 & ~B3) | (ack & Wait);
    // S1 next: from S (d=1)
    assign next_state[1] = (d & S);
    // S11 next: from S1 (d=1)
    assign next_state[2] = (d & S1);
    // S110 next: from S11 (d=1)
    assign next_state[3] = (d & S11);
    // B0 next: from S110 (d=1)
    assign next_state[4] = (d & S110);
    // B1 next: from B0 (always)
    assign next_state[5] = B0;
    // B2 next: from B1 (always)
    assign next_state[6] = B1;
    // B3 next: from B2 (always)
    assign next_state[7] = B2;
    // Count next: from B3 (always)
    assign next_state[8] = B3;
    // Wait next: from Count (done_counting=1)
    assign next_state[9] = (done_counting & Count);

    // output assignments (Moore machine: outputs depend only on current state)
    // B3_next: assert when current state is B3
    assign B3_next = B3;
    // S_next: assert when current state is S
    assign S_next = S;
    // S1_next: assert when current state is S1
    assign S1_next = S1;
    // Count_next: assert when current state is Count
    assign Count_next = Count;
    // Wait_next: assert when current state is Wait
    assign Wait_next = Wait;
    // done: asserted in Wait state
    assign done = Wait;
    // counting: asserted in Count state
    assign counting = Count;
    // shift_ena: asserted in B0, B1, B2, B3 states
    assign shift_ena = B0 | B1 | B2 | B3;

endmodule
